package com.primehr.rewardsrecognition.api;
import com.primehr.rewardsrecognition.api.RrEvaluationDtos.*;import com.primehr.rewardsrecognition.application.RrEvaluationService;import com.primehr.security.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/primehr/v1/rewards-recognition") public class RrEvaluationController{private final RrEvaluationService service;private final RrEvaluationPermissionGuard permission;private final AgencyScopeResolver agency;public RrEvaluationController(RrEvaluationService s,RrEvaluationPermissionGuard p,AgencyScopeResolver a){service=s;permission=p;agency=a;}private String agency(Authentication a){return agency.resolveAgencyId(a);}private static String actor(Authentication a){if(a==null||a.getName()==null||a.getName().isBlank())throw new org.springframework.security.access.AccessDeniedException("Authenticated employee identity is required");return a.getName();}private static String c(String v){return v;}
 @GetMapping("/evaluation-cases")public List<CaseResponse>cases(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t){return service.cases(agency(a),actor(a),permission.require(RrEvaluationPermissionGuard.EVALUATION,PrimeHrAction.ACCESS,t));}
 @GetMapping("/evaluation-cases/{id}")public CaseResponse get(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@PathVariable String id){return service.get(agency(a),id,actor(a),permission.require(RrEvaluationPermissionGuard.EVALUATION,PrimeHrAction.ACCESS,t));}
 @PostMapping("/nominations/{id}/evaluation")@ResponseStatus(HttpStatus.CREATED)public CaseResponse initialize(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody InitializeInput in){var scope=permission.require(RrEvaluationPermissionGuard.ELIGIBILITY,PrimeHrAction.EDIT,t);if(scope!=com.primehr.integration.administrative.PermissionDataScope.AGENCY_WIDE)throw new org.springframework.security.access.AccessDeniedException("Evaluation case initialization requires Agency Wide scope");return service.initialize(agency(a),id,in,actor(a),c);}
 @PutMapping("/evaluation-cases/{id}/eligibility")public CaseResponse eligibility(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody EligibilityInput in){var scope=permission.require(RrEvaluationPermissionGuard.ELIGIBILITY,PrimeHrAction.APPROVE,t);service.get(agency(a),id,actor(a),scope);return service.eligibility(agency(a),id,in,actor(a),c);}
 @PostMapping("/evaluation-cases/{id}/assignments/{assignmentId}/conflict")public CaseResponse conflict(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@PathVariable String assignmentId,@Valid@RequestBody ConflictInput in){var scope=permission.require(RrEvaluationPermissionGuard.EVALUATION,PrimeHrAction.EDIT,t);return service.conflict(agency(a),id,assignmentId,in,actor(a),scope,c);}
 @PostMapping("/evaluation-cases/{id}/assignments/{assignmentId}/replacement")public CaseResponse replace(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@PathVariable String assignmentId,@Valid@RequestBody ReplacementInput in){var scope=permission.require(RrEvaluationPermissionGuard.EVALUATION,PrimeHrAction.APPROVE,t);service.get(agency(a),id,actor(a),scope);return service.replace(agency(a),id,assignmentId,in,actor(a),c);}
 @PutMapping("/evaluation-cases/{id}/assignments/{assignmentId}/score")public CaseResponse score(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@PathVariable String assignmentId,@Valid@RequestBody ScoreInput in){permission.require(RrEvaluationPermissionGuard.EVALUATION,PrimeHrAction.SUBMIT,t);return service.score(agency(a),id,assignmentId,in,actor(a),c);}
 @PostMapping("/evaluation-cases/{id}/recommendation")public CaseResponse recommend(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody RecommendationInput in){var scope=permission.require(RrEvaluationPermissionGuard.EVALUATION,PrimeHrAction.APPROVE,t);service.get(agency(a),id,actor(a),scope);return service.recommend(agency(a),id,in,actor(a),c);}
 @PostMapping("/evaluation-cases/{id}/decision")public CaseResponse decide(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody DecisionInput in){permission.require(RrEvaluationPermissionGuard.AWARD,PrimeHrAction.FINALIZE,t);return service.decide(agency(a),id,in,actor(a),c);}
 @PostMapping("/evaluation-cases/{id}/issues")@ResponseStatus(HttpStatus.CREATED)public CaseResponse issue(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody IssueInput in){permission.require(RrEvaluationPermissionGuard.AWARD,PrimeHrAction.SUBMIT,t);return service.issue(agency(a),id,in,actor(a),c);}
 @PostMapping("/evaluation-cases/{id}/issues/{issueId}/resolve")public CaseResponse resolve(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@PathVariable String issueId,@Valid@RequestBody ResolveIssueInput in){permission.require(RrEvaluationPermissionGuard.AWARD,PrimeHrAction.APPROVE,t);return service.resolveIssue(agency(a),id,issueId,in,actor(a),c);}
}
